import * as THREE from 'three/webgpu';
import { texture, uv, vec4, uniform, mix } from 'three/tsl';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'home-subhead';
  group.position.set(0, 1.85, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const width = 3.2;
  const height = 2.0;

  const geometry = new THREE.PlaneGeometry(width, height);
  const material = new THREE.MeshBasicNodeMaterial({ transparent: true });

  const map = ctx.textureLoader.load('/prism-mock/home/nodes/cta-hero-isolated.png');
  map.colorSpace = THREE.SRGBColorSpace;

  const grainStrength = uniform(0.03);
  const texNode = texture(map, uv());

  // subtle static grain via a pseudo-random pattern based on uv
  const uvNode = uv();
  const grain = uvNode.x.mul(12.9898).add(uvNode.y.mul(78.233)).sin().mul(43758.5453).fract();
  const grained = texNode.rgb.add(grain.sub(0.5).mul(grainStrength));

  material.colorNode = vec4(grained, texNode.a);

  const plane = new THREE.Mesh(geometry, material);
  plane.name = 'home-subhead-plane';
  group.add(plane);

  // Headline text rendered via MSDF atlas
  const textMesh = createTextMesh({
    text: 'Atelier Noir — precise · luxury · technical',
    font: 'Lora',
    weight: 400,
    sizeEm: 0.34,
    color: '#e8ecf2',
    align: 'center',
    fontAtlas: ctx.fontAtlas,
  });
  textMesh.name = 'home-subhead-text';
  textMesh.position.set(0, 0, 0.01);
  group.add(textMesh);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map && map.dispose) map.dispose();
    if (textMesh.geometry) textMesh.geometry.dispose();
    if (textMesh.material) textMesh.material.dispose();
  };

  return group;
}
